	let evn = this.Env();
	let content = "";
	let text = res.data.paragraphs;
    if (!text) {
        return res.data.msg || "暂无数据，请稍后再试~";
    }
  let enabledPara = res.data.comment.enabled;
  let bubble = enabledPara ? res.data.comment.bubble.svg : "";
  let enabledChapter = res.data.comment.chapter_enabled;
  let chapterSvgs = enabledChapter ? res.data.comment.chapter_card.svg : "";

  var contents = [];
